select

from survey_common_area_price

where delete_flag=0 and task_id = #{taskId,jdbcType=INTEGER} and area_id = #{areaId,jdbcType=BIGINT}
    and city_type = #{cityType,jdbcType=INTEGER}

    and task_info_content_id = #{taskInfoContentId,jdbcType=BIGINT}


    and direction_result_type_id = #{directionResultTypeId,jdbcType=BIGINT}


    and price_type = #{priceType,jdbcType=INTEGER}

