mapper.select:
select p.area_id as areaId, p.area_name as areaName,p.city_type as cityType, p.task_id as taskId, p.task_name as TaskName, ca.city_type as areaType, max(case when p.task_id=18 then p.price else null end) as taskPriceMZ, max(case when p.task_id=17 then p.price else null end) as taskPriceQY, max(case when p.task_id=16 then p.price else null end) as taskPriceSC, max(case when p.task_id=15 then p.price else null end) as taskPriceTJ, max(case when p.task_id=14 then p.price else null end) as taskPriceKC, max(case when p.task_id=13 then p.price else null end) as taskPriceYL, max(case when p.task_id=12 then p.price else null end) as taskPriceBL, max(case when p.task_id=11 then p.price else null end) as taskPriceSD, max(case when p.task_id=10 then p.price else null end) as taskPriceYB, max(case when p.task_id=9 then p.price else null end) as taskPriceZF FROM survey_common_area_price p left join common_area ca on p.area_id = ca.area_id where p.delete_flag =0
and p.area_name like CONCAT(CONCAT('%',#{areaName,jdbcType=VARCHAR}), '%')
and p.area_id = #{areaId,jdbcType=BIGINT}
and p.task_id = #{taskId,jdbcType=INTEGER}
and p.city_type = #{cityType,jdbcType=INTEGER}
GROUP BY p.area_id,p.city_type

