mapper.select:
select A.area_id as areaId,A.city_type as cityType,A.str as strPirce, A.area_name as areaName, A.area_type as areaType, A.price_type as priceType from ( select t.area_id,t.city_type,t.area_name,t.area_type,t.price_type, GROUP_CONCAT(CONCAT(t.task_id,'_',t.task_info_content_id,'_',t.direction_result_type_id,'_',t.price)) str from ( SELECT p.area_id, p.area_name, p.city_type, p.task_id, p.task_info_content_id, p.direction_result_type_id, p.area_type, p.price_type, max(p.price) price FROM survey_common_area_price p where 1=1 and p.price >0 and p.price_type = #{priceType,jdbcType=INTEGER}
and p.area_name like CONCAT(CONCAT('%',#{areaName,jdbcType=VARCHAR}), '%')
and p.city_type = #{cityType,jdbcType=INTEGER}
GROUP BY p.area_id, p.city_type, p.task_id, p.task_info_content_id, p.direction_result_type_id ) t group by t.area_id,t.city_type) A
